-- Theme picker: lists the themes in lua/theme-data.lua (generated by
-- chezmoi from .chezmoidata.yaml). Selecting one recolors this nvim
-- instance immediately, then syncs WezTerm/starship/future nvim launches
-- asynchronously via the `theme-sync` script — no `chezmoi apply` needed.
local function pick_theme()
	local pickers = require("telescope.pickers")
	local finders = require("telescope.finders")
	local conf = require("telescope.config").values
	local actions = require("telescope.actions")
	local action_state = require("telescope.actions.state")

	local theme_data = require("theme-data")

	-- The sync script is a .sh on PATH everywhere except Windows, where
	-- PowerShell won't exec a bare .ps1 via jobstart without a host.
	local function sync_cmd(slug)
		if vim.fn.has("win32") == 1 then
			return { "powershell", "-NoProfile", "-File", vim.fn.expand("~/.local/bin/theme-sync.ps1"), slug }
		end
		return { "theme-sync", slug }
	end

	local slugs = {}
	for slug in pairs(theme_data.themes) do
		table.insert(slugs, slug)
	end
	table.sort(slugs)

	pickers
		.new({}, {
			prompt_title = "Theme",
			finder = finders.new_table({
				results = slugs,
				entry_maker = function(slug)
					return {
						value = slug,
						display = theme_data.themes[slug].name,
						ordinal = theme_data.themes[slug].name,
					}
				end,
			}),
			sorter = conf.generic_sorter({}),
			attach_mappings = function(prompt_bufnr, map)
				actions.select_default:replace(function()
					actions.close(prompt_bufnr)
					local slug = action_state.get_selected_entry().value
					local theme = theme_data.themes[slug]

					require("base16-colorscheme").setup(theme.palette)

					vim.fn.jobstart(sync_cmd(slug), {
						on_exit = function(_, code)
							if code == 0 then
								vim.notify("Theme set to " .. theme.name)
							else
								vim.notify("theme-sync failed for " .. theme.name, vim.log.levels.ERROR)
							end
						end,
					})
				end)
				return true
			end,
		})
		:find()
end

return {
	"nvim-telescope/telescope.nvim",
	dependencies = { "nvim-lua/plenary.nvim" },
	keys = {
		{ "<leader>ff", "<cmd>Telescope find_files<cr>", desc = "Find files" },
		{ "<leader>fg", "<cmd>Telescope live_grep<cr>", desc = "Live grep" },
		{ "<leader>fb", "<cmd>Telescope buffers<cr>", desc = "Buffers" },
		{ "<leader>ft", pick_theme, desc = "Pick theme" },
	},
}
